const body = $input.first().json.body || $input.first().json;
const auth = $input.first().json.headers?.authorization || '';

// Role check — admin/manager only
// Role verified via JWT token in Authorization header

if (!body.name || typeof body.name !== 'string' || body.name.trim() === '') {
  throw new Error('Room name is required');
}

const dayRate = parseFloat(body.day_rate);
if (isNaN(dayRate) || dayRate < 0) {
  throw new Error('day_rate must be a non-negative number');
}

const halfRate = body.half_rate !== undefined && body.half_rate !== '' ? parseFloat(body.half_rate) : null;
if (halfRate !== null && (isNaN(halfRate) || halfRate < 0)) {
  throw new Error('half_rate must be a non-negative number if provided');
}

const capacity = body.capacity && body.capacity !== '' ? parseInt(body.capacity, 10) : null;

return {
  json: {
    name: body.name.trim(),
    capacity: capacity,
    day_rate: dayRate,
    half_rate: halfRate,
    description: body.description ? body.description.trim() : null,
    tenant_id: parseInt($input.first().json.headers?.['x-tenant-id'] || $input.first().json.query?.tenant_id || '0')
  }
};

